"""Sample PDFs used by the tests (all generated by code in tests/pdfgen.py)."""

from __future__ import annotations

import logging
from pathlib import Path

import pikepdf

from pdfgen import (BOLD, Builder, add_signature, add_text_field, filled_rect, hline, image_xobject, paragraph_ops,
                    single_line, vline, wrap)

logging.getLogger("fontTools").setLevel(logging.ERROR)

DIGITS = "0123456789"
EXTRA = "%£$.,;:()-'/&"

PARA_A = ("This report describes the controls in place for the financial year ending 31 December 2023. "
          "All staff must complete the anti-bribery training within 30 days of joining. Managers review "
          "access rights every quarter and record exceptions in the risk register.")
PARA_B = ("Customer complaints are logged within two working days and resolved within eight weeks. "
          "The board receives a summary of complaints each month.")
PARA_C = ("Suppliers are assessed before onboarding and reviewed every year. Contracts above the approval "
          "limit need sign-off from the finance director.")
LEFT_COL = "Retention: records are kept for six years after the end of the relationship."
RIGHT_COL = "Disposal: paper records are shredded on site by an approved contractor."
TABLE = [("Control", "Owner", "Frequency"), ("Access review", "IT Security", "Quarterly"),
         ("Training", "HR", "Annually"), ("Supplier audit", "Procurement", "Every two years")]
TOC = ("Section 4 Data protection", "12")
PAGE2 = ("Revenue grew by 12% to 4.2 million. The policy applies to all staff. "
         "The policy applies to all contractors as well.")


def _all_text() -> str:
    parts = [PARA_A, PARA_B, PARA_C, LEFT_COL, RIGHT_COL, PAGE2, TOC[0], TOC[1], "Annual Compliance Report",
             "Confidential - internal use only", "Page 1", "Page 2", "Policy name", "Owner", "Anti-bribery policy 2023",
             "Compliance team", "Signed by"]
    for row in TABLE:
        parts.extend(row)
    return " ".join(parts) + DIGITS + EXTRA


def report_pdf(path: Path, style: str = "td", font_kind: str = "truetype", encoding: str = "WinAnsiEncoding") -> Path:
    """Two-page report with paragraphs, a heading, a table, a TOC line and two columns."""
    b = Builder()
    chars = _all_text()
    if font_kind == "type0":
        f1 = b.font_type0("F1", chars)
    elif font_kind == "helvetica":
        f1 = b.font_helvetica("F1")
    elif font_kind == "differences":
        f1 = b.font_truetype("F1", chars, differences=True)
    else:
        f1 = b.font_truetype("F1", chars, encoding=encoding)
    f2 = b.font_truetype("F2", "Annual Compliance Report" + DIGITS, path=BOLD)
    W = 612
    c = []
    c.append(single_line(f2, "Annual Compliance Report", 72, 740, 16))
    lines = wrap(f1, PARA_A, 11, 460)
    c.append(paragraph_ops(f1, lines, 72, 710, 11, 14, style))
    lines_b = wrap(f1, PARA_B, 11, 460)
    c.append(paragraph_ops(f1, lines_b, 72, 640, 11, 14, "lines" if style == "td" else style))
    # table
    top = 590
    xs = [72, 220, 360, 520]
    row_h = 20
    for i, row in enumerate(TABLE):
        y = top - i * row_h
        for j, cell in enumerate(row):
            c.append(single_line(f1, cell, xs[j] + 4, y - 14, 10))
    for i in range(len(TABLE) + 1):
        c.append(hline(xs[0], xs[-1], top - i * row_h))
    for x in xs:
        c.append(vline(x, top - len(TABLE) * row_h, top))
    # TOC line with dot leaders
    toc_y = 480
    title_w = f1.width(TOC[0], 11)
    dots_x0 = 72 + title_w + 6
    num_w = f1.width(TOC[1], 11)
    dot_w = f1.width(".", 11)
    n_dots = int((520 - num_w - 6 - dots_x0) / dot_w)
    c.append(single_line(f1, TOC[0], 72, toc_y, 11))
    c.append(single_line(f1, "." * n_dots, dots_x0, toc_y, 11))
    c.append(single_line(f1, TOC[1], 520 - num_w, toc_y, 11))
    # two columns with a narrow gutter
    lc = wrap(f1, LEFT_COL, 10, 220)
    rc = wrap(f1, RIGHT_COL, 10, 220)
    c.append(paragraph_ops(f1, lc, 72, 440, 10, 13, "td"))
    c.append(paragraph_ops(f1, rc, 310, 440, 10, 13, "td"))
    # shaded box with a paragraph inside
    c.append(filled_rect(66, 330, 546, 380, 0.92))
    c.append(paragraph_ops(f1, wrap(f1, PARA_C, 10, 460), 72, 366, 10, 13, "td"))
    c.append(single_line(f1, "Page 1", 290, 40, 9))
    b.page(b"\n".join(c), b.resources([f1, f2]), size=(W, 792))
    # page 2
    c2 = [paragraph_ops(f1, wrap(f1, PAGE2, 11, 460), 72, 720, 11, 14, style), single_line(f1, "Page 2", 290, 40, 9)]
    b.page(b"\n".join(c2), b.resources([f1, f2]))
    return b.save(path)


def shared_stream_pdf(path: Path) -> Path:
    """Two pages whose /Contents is the very same stream object."""
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    stream = b.pdf.make_stream(paragraph_ops(f1, wrap(f1, PARA_A, 11, 460), 72, 700, 11, 14, "td"))
    res = b.resources([f1])
    b.page(stream, res, indirect_resources=True)
    b.pdf.pages.append(pikepdf.Page(pikepdf.Dictionary(Type=pikepdf.Name.Page, MediaBox=[0, 0, 612, 792],
                                                       Contents=stream, Resources=b.pdf.pages[0].obj.Resources)))
    return b.save(path)


def xobject_pdf(path: Path) -> Path:
    """A form XObject with text shared by two pages, drawn twice on page 1."""
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    xres = b.resources([f1])
    fx = b.form_xobject(single_line(f1, "Confidential - internal use only", 0, 0, 9), xres, bbox=(0, -5, 300, 15))
    res = b.resources([f1], xobjects={"Fx1": fx})
    body = paragraph_ops(f1, wrap(f1, PARA_B, 11, 460), 72, 700, 11, 14, "td")
    p1 = b"q 1 0 0 1 72 760 cm /Fx1 Do Q\n" + body + b"\nq 1 0 0 1 72 30 cm /Fx1 Do Q"
    b.page(p1, res, indirect_resources=True)
    p2 = b"q 1 0 0 1 72 760 cm /Fx1 Do Q\n" + paragraph_ops(f1, wrap(f1, PARA_C, 11, 460), 72, 700, 11, 14, "td")
    b.page(p2, b.pdf.pages[0].obj.Resources)
    return b.save(path)


def multistream_pdf(path: Path) -> Path:
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    s1 = single_line(f1, "Annual Compliance Report", 72, 740, 14)
    s2 = paragraph_ops(f1, wrap(f1, PARA_A, 11, 460), 72, 700, 11, 14, "tstar")
    s3 = paragraph_ops(f1, wrap(f1, PARA_B, 11, 460), 72, 600, 11, 14, "quote")
    b.page([s1, s2, s3], b.resources([f1]))
    return b.save(path)


def form_pdf(path: Path) -> Path:
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    helv = b.font_helvetica("Helv")
    page = b.page(single_line(f1, "Policy name", 72, 700, 11) + b"\n" + single_line(f1, "Owner", 72, 660, 11)
                  + b"\n" + paragraph_ops(f1, wrap(f1, PARA_B, 11, 460), 72, 600, 11, 14, "td"),
                  b.resources([f1]))
    add_text_field(b, page, "PolicyName", "Anti-bribery policy 2023", (180, 692, 420, 712), helv, 10)
    add_text_field(b, page, "Owner", "Compliance team", (180, 652, 420, 672), helv, 10)
    return b.save(path)


def signed_pdf(path: Path) -> Path:
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    page = b.page(paragraph_ops(f1, wrap(f1, PARA_A, 11, 460), 72, 700, 11, 14, "td"), b.resources([f1]))
    add_signature(b, page)
    return b.save(path)


def scanned_pdf(path: Path, ocr: bool = True) -> Path:
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    img = image_xobject(b)
    content = b"q 612 0 0 792 0 0 cm /Im1 Do Q"
    if ocr:
        content += b"\nBT 3 Tr " + paragraph_ops(f1, wrap(f1, PARA_A, 11, 460), 72, 700, 11, 14, "td")[2:]
    b.page(content, b.resources([f1], xobjects={"Im1": img}))
    return b.save(path)


def graphic_text_pdf(path: Path) -> Path:
    """The words 'Total 2023' are drawn as vector outlines, not as text."""
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    outline = b"q 0 g 72 600 m 80 600 l 80 620 l 72 620 l f 84 600 m 92 600 l 92 620 l 84 620 l f Q"
    content = single_line(f1, "Summary", 72, 640, 12) + b"\n" + outline
    b.page(content, b.resources([f1]))
    return b.save(path)


def justified_pdf(path: Path) -> Path:
    """A justified paragraph (word spacing set with Tw) and a paragraph with a bold word."""
    b = Builder()
    f1 = b.font_truetype("F1", _all_text())
    f2 = b.font_truetype("F2", _all_text(), path=BOLD)
    lines = wrap(f1, PARA_A + " " + PARA_C, 11, 420)
    c = [paragraph_ops(f1, lines, 72, 720, 11, 14, "lines", justify_width=420)]
    mixed = (b"BT /F1 11 Tf 72 560 Td " + f1.lit("Suppliers are ") + b" Tj /F2 11 Tf " + f1.lit("x")[:0]
             + f2.lit("always") + b" Tj /F1 11 Tf " + f1.lit(" assessed before onboarding and reviewed every year.")
             + b" Tj 0 -14 Td " + f1.lit("Contracts above the approval limit need sign-off.") + b" Tj ET")
    c.append(mixed)
    b.page(b"\n".join(c), b.resources([f1, f2]))
    return b.save(path)


def build_all(directory: Path) -> dict[str, Path]:
    directory.mkdir(parents=True, exist_ok=True)
    out = {
        "report": report_pdf(directory / "report.pdf"),
        "report_mac": report_pdf(directory / "report_mac.pdf", style="mac"),
        "report_type0": report_pdf(directory / "report_type0.pdf", font_kind="type0", style="tstar"),
        "report_helvetica": report_pdf(directory / "report_helvetica.pdf", font_kind="helvetica", style="quote"),
        "report_differences": report_pdf(directory / "report_differences.pdf", font_kind="differences", style="mac"),
        "report_macroman": report_pdf(directory / "report_macroman.pdf", encoding="MacRomanEncoding", style="words"),
        "shared_stream": shared_stream_pdf(directory / "shared_stream.pdf"),
        "xobject": xobject_pdf(directory / "xobject.pdf"),
        "multistream": multistream_pdf(directory / "multistream.pdf"),
        "form": form_pdf(directory / "form.pdf"),
        "signed": signed_pdf(directory / "signed.pdf"),
        "scanned": scanned_pdf(directory / "scanned.pdf"),
        "graphic_text": graphic_text_pdf(directory / "graphic_text.pdf"),
        "justified": justified_pdf(directory / "justified.pdf"),
    }
    return out
